/* ============================================================
 * colosseum.js — Flavian Amphitheatre (Colosseum)
 * East of the Forum, near the Caelian and Esquiline hills.
 * Elliptical ring, 4 tiers of arcades, cavea seating.
 * ============================================================ */
function initColosseum(scene) {
  const cx = 120, cz = 120;
  const a = 52, b = 42; // ellipse radii
  const y = ROME.terrainHeight(cx, cz);
  const trav = ROME.MAT.travertine, marble = ROME.MAT.marble, brick = ROME.MAT.brick;

  const g = new THREE.Group();
  const N = 48;

  // tiered outer walls (elliptical ring), height ~48 m
  const tierH = [14, 12, 12, 8];
  let yy = 0;
  tierH.forEach((h, ti) => {
    const shape = new THREE.Shape();
    const inner = new THREE.Path();
    for (let i = 0; i <= N; i++) {
      const t = i / N * Math.PI * 2;
      const X = Math.cos(t) * a, Z = Math.sin(t) * b;
      i === 0 ? shape.moveTo(X, Z) : shape.lineTo(X, Z);
    }
    for (let i = N; i >= 0; i--) {
      const t = i / N * Math.PI * 2;
      inner.lineTo(Math.cos(t) * (a - 4), Math.sin(t) * (b - 4));
    }
    inner.closePath();
    shape.holes.push(inner);
    const geo = new THREE.ExtrudeGeometry(shape, { depth: h, bevelEnabled: false });
    const m = new THREE.Mesh(geo, ti === 3 ? brick : trav);
    m.rotation.x = -Math.PI / 2;
    m.position.y = yy;
    m.castShadow = m.receiveShadow = true;
    g.add(m);
    yy += h;
  });

  // arcade columns along the outer face (first three tiers)
  const colGeo = new THREE.CylinderGeometry(1.1, 1.3, 9, 10);
  const archGeo = new THREE.TorusGeometry(3.2, 0.55, 6, 12, Math.PI);
  const M = 96;
  for (let i = 0; i < M; i++) {
    const t = (i + 0.5) / M * Math.PI * 2;
    const X = Math.cos(t) * (a + 0.5), Z = Math.sin(t) * (b + 0.5);
    for (let ti = 0; ti < 3; ti++) {
      const cy = 3 + ti * 13;
      const c = new THREE.Mesh(colGeo, marble);
      c.position.set(X, cy, Z);
      c.scale.y = 0.55;
      g.add(c);
      const arc = new THREE.Mesh(archGeo, marble);
      arc.position.set(X, cy - 1.5, Z);
      arc.rotation.y = Math.atan2(Math.cos(t) * a, -Math.sin(t) * b);
      g.add(arc);
    }
  }

  // cavea: elliptical seating bowl (inverted cone ring)
  const cavea = new THREE.Mesh(
    new THREE.CylinderGeometry(30, 36, 16, 40, 1, true), brick);
  cavea.scale.set(a / 34, 1, b / 34);
  cavea.position.y = 10;
  g.add(cavea);
  // arena floor
  const floor = new THREE.Mesh(new THREE.CircleGeometry(1, 40), ROME.MAT.sand);
  floor.scale.set(a * 0.62, 1, b * 0.62);
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = 1.5;
  floor.receiveShadow = true;
  g.add(floor);

  g.position.set(cx, y, cz);
  scene.add(g);
  ROME.makeLabel(scene, 'Colosseum (Flavian Amphitheatre)', cx, cz, y);
}

/* ============================================================
 * circuses.js — Circus Maximus
 * Massive chariot-racing track in the valley between the
 * Palatine and Aventine hills, with spina, obelisk and
 * tiered spectator stands (the "Maximus" of Rome).
 * ============================================================ */
function initCircuses(scene) {
  const cx = -10, cz = 40;
  const L = 400, W = 85; // length & width of the track
  const trav = ROME.MAT.travertine, brick = ROME.MAT.brick;
  const marble = ROME.MAT.marble, sand = ROME.MAT.sand;

  const g = new THREE.Group();

  // arena sand floor (elongated U)
  const track = new THREE.Shape();
  const r = W;
  track.absarc(0, 0, r, 0, Math.PI, false);
  track.lineTo(r, L);
  track.absarc(0, L, r, Math.PI, Math.PI * 2, false);
  track.closePath();
  // inner hole -> a ring would leave ends open; use solid U instead:
  const shape2 = new THREE.Shape();
  const N = 24;
  for (let i = 0; i <= N; i++) {
    const t = Math.PI - i / N * Math.PI;
    const X = Math.cos(t) * r, Z = Math.sin(t) * r;
    i === 0 ? shape2.moveTo(X, Z) : shape2.lineTo(X, Z);
  }
  shape2.lineTo(r, L);
  shape2.lineTo(-r, L);
  shape2.closePath();
  const floorGeo = new THREE.ExtrudeGeometry(shape2, { depth: 0.6, bevelEnabled: false });
  const floorM = new THREE.Mesh(floorGeo, sand);
  floorM.rotation.x = Math.PI / 2;
  floorM.position.y = 0.3;
  floorM.receiveShadow = true;
  g.add(floorM);

  // tiered seating: straight banks + curved start end
  const bankGeo = new THREE.BoxGeometry(1, 1, 1);
  const tiers = 6, tierH = 3.2, tierD = 5;
  // curved (west) end, elliptical tiers
  for (let i = 0; i < tiers; i++) {
    const off = i * tierD + 4;
    const ring = new THREE.Shape();
    const inner = new THREE.Path();
    const M = 36;
    for (let k = 0; k <= M; k++) {
      const t = k / M * Math.PI * 2;
      const X = Math.cos(t) * (r + off), Z = Math.sin(t) * (r + off) * 0.75;
      k === 0 ? ring.moveTo(X, Z) : ring.lineTo(X, Z);
    }
    for (let k = M; k >= 0; k--) {
      const t = k / M * Math.PI * 2;
      inner.lineTo(Math.cos(t) * (r + off - 3), Math.sin(t) * (r + off - 3) * 0.75);
    }
    inner.closePath();
    ring.holes.push(inner);
    const geo = new THREE.ExtrudeGeometry(ring, { depth: tierH, bevelEnabled: false });
    const m = new THREE.Mesh(geo, i % 2 ? trav : brick);
    m.rotation.x = -Math.PI / 2;
    m.position.y = i * tierH;
    m.castShadow = true;
    g.add(m);
  }
  // straight east bank
  const bank = new THREE.Mesh(bankGeo, trav);
  bank.scale.set(tiers * tierD + 10, tiers * tierH, L + r * 1.5);
  bank.position.set(r + (tiers * tierD + 10) / 2, tiers * tierH / 2, L / 2);
  bank.castShadow = true;
  g.add(bank);

  // spina (central barrier) with obelisk
  const spina = new THREE.Mesh(bankGeo, marble);
  spina.scale.set(6, 2.5, L * 0.7);
  spina.position.set(0, 1.25, L * 0.55);
  spina.castShadow = true;
  g.add(spina);
  // obelisk on the spina
  const ob = new THREE.Mesh(new THREE.ConeGeometry(1.6, 24, 4), ROME.MAT.obsidian);
  ob.position.set(0, 2.5 + 12, L * 0.55);
  ob.rotation.y = Math.PI / 4;
  g.add(ob);
  const pyramidion = new THREE.Mesh(new THREE.ConeGeometry(0.8, 2, 4), ROME.MAT.gold);
  pyramidion.position.set(0, 2.5 + 25, L * 0.55);
  pyramidion.rotation.y = Math.PI / 4;
  g.add(pyramidion);
  // goal eggs (ova) and horse statuettes on the spina
  for (let i = 1; i <= 7; i++) {
    const egg = new THREE.Mesh(new THREE.SphereGeometry(1, 8, 8), ROME.MAT.gold);
    egg.position.set(0, 3.5, L * (i / 8));
    g.add(egg);
  }

  // Palatine palace wall along the west edge (palaces of emperors)
  const palace = new THREE.Mesh(bankGeo, ROME.MAT.brick);
  palace.scale.set(4, 9, L * 0.9);
  palace.position.set(-r - 8, 4.5, L * 0.45);
  palace.castShadow = true;
  g.add(palace);
  const palRoof = new THREE.Mesh(bankGeo, ROME.MAT.roof);
  palRoof.scale.set(5, 1, L * 0.9);
  palRoof.position.set(-r - 8, 9.5, L * 0.45);
  g.add(palRoof);

  const baseY = ROME.terrainHeight(cx, cz) - 1;
  g.position.set(cx, baseY, cz - L / 2);
  scene.add(g);
  ROME.makeLabel(scene, 'Circus Maximus', cx, cz + L / 2, ROME.terrainHeight(cx, cz + L / 2));
  ROME.makeLabel(scene, 'Imperial Palaces (Palatine)', cx, cz - 30, ROME.terrainHeight(cx - 100, cz - 30) + 12);
}

/* ============================================================
 * bathes.js — Public bathes (thermae)
 *  - Baths of Caracalla (near Via Appia)
 *  - Baths of Diocletian (Quirinal / Baths of Constantine)
 *  - Baths of Trajan (Esquiline)
 * Large halls with apses, flat roofs, colonnaded gardens,
 * hypocaust-heated pools (caldarium / frigidarium).
 * ============================================================ */
function buildBaths(scene, x, z, name, scale, rotY) {
  scale = scale || 1;
  rotY = rotY || 0;
  const y = ROME.terrainHeight(x, z);
  const trav = ROME.MAT.travertine, brick = ROME.MAT.brick;
  const marble = ROME.MAT.marble, water = ROME.MAT.water;

  const g = new THREE.Group();

  // main hall block
  const hall = new THREE.Mesh(new THREE.BoxGeometry(60 * scale, 12 * scale, 34 * scale), trav);
  hall.position.y = 6 * scale; hall.castShadow = hall.receiveShadow = true;
  g.add(hall);
  // apse (semi-circular end)
  const apse = new THREE.Mesh(new THREE.CylinderGeometry(17 * scale, 17 * scale, 13 * scale, 20, 1, false, 0, Math.PI), trav);
  apse.rotation.y = -Math.PI / 2;
  apse.position.set(30 * scale, 6.5 * scale, 0);
  apse.castShadow = true;
  g.add(apse);
  // roof
  const roof = new THREE.Mesh(new THREE.BoxGeometry(62 * scale, 1.2 * scale, 36 * scale), ROME.MAT.roof);
  roof.position.y = 12.6 * scale;
  g.add(roof);
  // colonnade along the front
  const colGeo = new THREE.CylinderGeometry(0.9 * scale, 1 * scale, 8 * scale, 10);
  for (let i = 0; i <= 8; i++) {
    const c = new THREE.Mesh(colGeo, marble);
    c.position.set(-30 * scale + i * 7.5 * scale, 4 * scale, 20 * scale);
    c.castShadow = true;
    g.add(c);
  }
  const ent = new THREE.Mesh(new THREE.BoxGeometry(62 * scale, 1.4 * scale, 2.2 * scale), marble);
  ent.position.set(0, 8.6 * scale, 20 * scale);
  g.add(ent);
  // reflecting pool (frigidarium) in front garden
  const pool = new THREE.Mesh(new THREE.BoxGeometry(24 * scale, 0.8 * scale, 10 * scale), water);
  pool.position.set(0, 0.6 * scale, 30 * scale);
  g.add(pool);
  const poolRim = new THREE.Mesh(new THREE.BoxGeometry(26 * scale, 1.4 * scale, 12 * scale), marble);
  poolRim.position.y = 0.5 * scale; poolRim.position.z = 30 * scale;
  g.add(poolRim);
  const poolWater = new THREE.Mesh(new THREE.BoxGeometry(24.6 * scale, 1.5 * scale, 10.6 * scale), water);
  poolWater.position.set(0, 0.9 * scale, 30 * scale);
  g.add(poolWater);

  g.position.set(x, y, z);
  g.rotation.y = rotY;
  scene.add(g);
  ROME.makeLabel(scene, name, x, z, y);
}

function initBathes(scene) {
  buildBaths(scene, 200, 480, 'Baths of Caracalla', 1.3, -Math.PI / 2 - 0.3);
  buildBaths(scene, 300, -330, 'Baths of Diocletian', 1.6, Math.PI * 0.9);
  buildBaths(scene, 440, 220, 'Baths of Trajan', 1.0, Math.PI / 4);
}

/* ============================================================
 * walls.js — Aurelian Walls (271–275 CE) + city gates
 * Brick-faced concrete circuit, ~10.6 m high after Stilicho,
 * defensive towers every ~30 m, 18 major gates aligned with
 * the consular roads (Porta Flaminia, Pinciana, Salaria,
 * Maggiore, Tiburtina, Esquilina, Asinaria, San Sebastiano,
 * San Paolo, Latina, Capena...).
 * ============================================================ */

const WALL_CX = 20, WALL_CZ = -40, WALL_R = 620;
const WALL_N = 220;

/* points along the Aurelian circuit, following terrain */
function wallPoints() {
  const pts = [];
  for (let i = 0; i <= WALL_N; i++) {
    const t = i / WALL_N * Math.PI * 2;
    // slightly irregular plan (ellipse-ish)
    const r = WALL_R * (1 + 0.04 * Math.sin(2 * t + 1));
    const x = WALL_CX + Math.cos(t) * r;
    const z = WALL_CZ + Math.sin(t) * r * 0.94;
    pts.push({ x, z, y: ROME.terrainHeight(x, z) });
  }
  return pts;
}

function buildGate(scene, angle, name, isMajor) {
  const r = WALL_R * (1 + 0.04 * Math.sin(2 * angle + 1));
  const x = WALL_CX + Math.cos(angle) * r;
  const z = WALL_CZ + Math.sin(angle) * r * 0.94;
  const y = ROME.terrainHeight(x, z);
  const g = new THREE.Group();
  const trav = ROME.MAT.travertine, brick = ROME.MAT.brick;

  const W = isMajor ? 16 : 10, H = 14, D = 8;
  // two piers
  for (const s of [-1, 1]) {
    const pier = new THREE.Mesh(new THREE.BoxGeometry(D, H, 3.5), brick);
    pier.position.set(0, H / 2, s * (W / 2 - 1.75));
    pier.castShadow = true; g.add(pier);
    const cap = new THREE.Mesh(new THREE.BoxGeometry(D + 1, 0.8, 4.5), trav);
    cap.position.set(0, H + 0.4, s * (W / 2 - 1.75)); g.add(cap);
  }
  // arch (half torus)
  const archR = W / 2 - 1.75;
  const arch = new THREE.Mesh(new THREE.TorusGeometry(archR, 1.4, 8, 16, Math.PI), trav);
  arch.position.y = H * 0.55;
  g.add(arch);
  // top beam + battlement
  const beam = new THREE.Mesh(new THREE.BoxGeometry(D + 1, 3.2, W + 2), brick);
  beam.position.y = H + 1.6; beam.castShadow = true; g.add(beam);
  const batt = new THREE.Mesh(new THREE.BoxGeometry(D + 1.5, 1.5, W + 2), trav);
  batt.position.y = H + 3.6; g.add(batt);

  g.position.set(x, y, z);
  g.rotation.y = -angle - Math.PI / 2; // face outward along the road
  scene.add(g);
  ROME.makeLabel(scene, name, x + Math.cos(angle) * 4, z + Math.sin(angle) * 4, y);
}

function initWalls(scene) {
  const pts = wallPoints();
  // curtain wall
  ROME.makeStrip(scene, {
    points: pts, material: ROME.MAT.brick,
    width: 3.6, thickness: 10.6, lift: 5.0
  });
  // merlons on top
  ROME.makeStrip(scene, {
    points: pts, material: ROME.MAT.tuff,
    width: 4.4, thickness: 1.2, lift: 10.6 + 0.5
  });
  // defensive towers every ~30 m (381 historically!)
  const towerGeo = new THREE.BoxGeometry(7, 13, 7);
  const towers = new THREE.InstancedMesh(towerGeo, ROME.MAT.brick, 100);
  const dummy = new THREE.Object3D();
  let ti = 0;
  for (let i = 0; i < pts.length - 1 && ti < 100; i += 5) {
    const p = pts[i];
    dummy.position.set(p.x, p.y + 6.5, p.z);
    dummy.rotation.y = 0;
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    towers.setMatrixAt(ti++, dummy.matrix);
  }
  towers.count = ti;
  towers.castShadow = true;
  scene.add(towers);

  /* ---------------- Gates (angle: 0 = east, CCW) ---------------- */
  const TAU = Math.PI * 2;
  const A = (deg) => deg * Math.PI / 180;
  buildGate(scene, A(-90),  'Porta Flaminia (Porta del Popolo)', true);  // north
  buildGate(scene, A(-125), 'Porta Pinciana', false);
  buildGate(scene, A(-55),  'Porta Salaria', false);
  buildGate(scene, A(-20),  'Porta Maggiore (Praenestina)', true);
  buildGate(scene, A(5),    'Porta Tiburtina', false);
  buildGate(scene, A(30),   'Porta Esquilina', false);
  buildGate(scene, A(60),   'Porta Asinaria', false);
  buildGate(scene, A(90),   'Porta San Sebastiano (Appia)', true);  // south
  buildGate(scene, A(135),  'Porta San Paolo (Ostiensis)', true);  // SSW
  buildGate(scene, A(115),  'Porta Latina', false);
  buildGate(scene, A(155),  'Porta Capena', false);
}

/* ============================================================
 * buildings.js — Roman Forum & civic buildings
 *  - Curia Julia (Senate house)
 *  - Rostra (speaker's platform with ship prows)
 *  - Basilica Julia & Basilica Aemilia
 *  - Tablinum / Temple of Castor & Pollux (three columns)
 *  - Via Sacra surroundings, market stalls, domus blocks
 * ============================================================ */
function initBuildings(scene) {
  const trav = ROME.MAT.travertine, brick = ROME.MAT.brick;
  const marble = ROME.MAT.marble, roof = ROME.MAT.roof;

  /* ---- Curia Julia (Senate house), west end of Forum ---- */
  (function () {
    const x = -90, z = -45, y = ROME.terrainHeight(x, z);
    const g = new THREE.Group();
    const body = new THREE.Mesh(new THREE.BoxGeometry(16, 9, 11), trav);
    body.position.y = 4.5; body.castShadow = true; g.add(body);
    // three front arches
    for (let i = -1; i <= 1; i++) {
      const arch = new THREE.Mesh(new THREE.TorusGeometry(2, 0.5, 6, 12, Math.PI), marble);
      arch.position.set(i * 4.5, 3.2, 5.55);
      g.add(arch);
    }
    const pedShape = new THREE.Shape();
    pedShape.moveTo(-8.5, 0); pedShape.lineTo(8.5, 0); pedShape.lineTo(0, 3.5); pedShape.closePath();
    const ped = new THREE.Mesh(new THREE.ExtrudeGeometry(pedShape, { depth: 1.2, bevelEnabled: false }), marble);
    ped.position.set(0, 9, 4.6);
    g.add(ped);
    const r = new THREE.Mesh(new THREE.BoxGeometry(17, 1.4, 12), roof);
    r.position.y = 10; g.add(r);
    g.position.set(x, y, z);
    g.rotation.y = -Math.PI / 2 - 0.2;
    scene.add(g);
    ROME.makeLabel(scene, 'Curia Julia (Senate House)', x, z, y);
  })();

  /* ---- Rostra: raised speaker platform with ship prows ---- */
  (function () {
    const x = -40, z = -25, y = ROME.terrainHeight(x, z);
    const g = new THREE.Group();
    const pl = new THREE.Mesh(new THREE.BoxGeometry(12, 3, 8), trav);
    pl.position.y = 1.5; pl.castShadow = true; g.add(pl);
    for (let i = 0; i < 4; i++) {
      const s = new THREE.Mesh(new THREE.BoxGeometry(13, 0.5, 1.4), marble);
      s.position.set(0, 0.25 + i * 0.72, 4.2 + (4 - i) * 0.3);
      g.add(s);
    }
    // ship prows (corvi) — curved bronze bows
    for (const s of [-3, 0, 3]) {
      const prow = new THREE.Mesh(new THREE.TorusGeometry(1.4, 0.18, 6, 10, Math.PI * 1.2), ROME.MAT.gold);
      prow.position.set(s, 3.5, 3.8);
      prow.rotation.y = Math.PI / 2;
      g.add(prow);
    }
    g.position.set(x, y, z);
    scene.add(g);
    ROME.makeLabel(scene, 'Rostra', x, z, y);
  })();

  /* ---- Basilica Julia (law court / market hall), south of forum ---- */
  (function () {
    const x = -90, z = 30, y = ROME.terrainHeight(x, z);
    const g = new THREE.Group();
    const body = new THREE.Mesh(new THREE.BoxGeometry(36, 8, 16), trav);
    body.position.y = 4; body.castShadow = true; g.add(body);
    const roofB = new THREE.Mesh(new THREE.BoxGeometry(37, 1.2, 17), roof);
    roofB.position.y = 8.6; g.add(roofB);
    // apse
    const apse = new THREE.Mesh(new THREE.CylinderGeometry(8, 8, 8, 16, 1, false, -Math.PI / 2, Math.PI), trav);
    apse.rotation.z = Math.PI / 2;
    apse.position.set(18, 4, 0);
    g.add(apse);
    // arcade
    const colGeo = new THREE.CylinderGeometry(0.8, 0.9, 7, 10);
    for (let i = 0; i <= 6; i++) {
      const c = new THREE.Mesh(colGeo, marble);
      c.position.set(-15 + i * 5, 3.5, 8.5);
      c.castShadow = true; g.add(c);
    }
    g.position.set(x, y, z);
    scene.add(g);
    ROME.makeLabel(scene, 'Basilica Julia', x, z, y);
  })();

  /* ---- Basilica Aemilia, east side of Forum ---- */
  (function () {
    const x = 85, z = 35, y = ROME.terrainHeight(x, z);
    const g = new THREE.Group();
    const body = new THREE.Mesh(new THREE.BoxGeometry(30, 7.5, 14), trav);
    body.position.y = 3.75; body.castShadow = true; g.add(body);
    const roofB = new THREE.Mesh(new THREE.BoxGeometry(31, 1.1, 15), roof);
    roofB.position.y = 8.1; g.add(roofB);
    g.position.set(x, y, z);
    g.rotation.y = Math.PI / 2;
    scene.add(g);
    ROME.makeLabel(scene, 'Basilica Aemilia', x, z, y);
  })();

  /* ---- Temple of Castor & Pollux (three surviving columns) ---- */
  (function () {
    const x = -8, z = 5, y = ROME.terrainHeight(x, z);
    const g = new THREE.Group();
    const colGeo = new THREE.CylinderGeometry(1.1, 1.3, 9, 14);
    const pos = [[-3, 0], [3, 0], [0, 4.5]];
    for (const [px, pz] of pos) {
      const c = new THREE.Mesh(colGeo, marble);
      c.position.set(px, 4.5, pz); c.castShadow = true; g.add(c);
      const cap = new THREE.Mesh(new THREE.BoxGeometry(3, 0.8, 3), marble);
      cap.position.set(px, 9.4, pz); g.add(cap);
    }
    g.position.set(x, y, z);
    scene.add(g);
    ROME.makeLabel(scene, 'Temple of Castor & Pollux', x, z, y);
  })();

  /* ---- Market stalls & domus blocks around the Forum ---- */
  const stallGeo = new THREE.BoxGeometry(4, 2.2, 3);
  const stallRoofGeo = new THREE.ConeGeometry(3.1, 1.6, 4);
  const stallPts = [];
  for (let i = 0; i < 14; i++) {
    const x = -70 + i * 9.5, z = -70 + (i % 2) * 12;
    if (Math.hypot(x, z) < 25) continue; // keep Via Sacra clear
    stallPts.push([x, z]);
  }
  for (const [x, z] of stallPts) {
    const y = ROME.terrainHeight(x, z);
    const s = new THREE.Mesh(stallGeo, ROME.MAT.wood);
    s.position.set(x, y + 1.1, z); s.rotation.y = Math.random() * 0.8 - 0.4;
    s.castShadow = true; scene.add(s);
    const sr = new THREE.Mesh(stallRoofGeo, ROME.MAT.roof);
    sr.position.set(x, y + 2.6, z);
    sr.rotation.y = Math.PI / 4 + Math.random() * 0.8 - 0.4;
    scene.add(sr);
  }

  /* ---- Insulae: dense brick apartment blocks (residential quarters) ---- */
  const insulaSpots = [
    [60, 170, 14, 12, 4], [85, 190, 12, 10, 3], [140, 160, 16, 12, 5],
    [170, 100, 13, 11, 4], [-170, 100, 12, 10, 3], [-200, 130, 14, 11, 4],
    [120, -160, 13, 10, 4], [90, -190, 15, 11, 3], [-60, 320, 14, 10, 4],
    [-10, 300, 12, 10, 3], [300, 420, 14, 12, 4], [-320, 300, 12, 10, 3],
    [260, -120, 13, 10, 4], [-190, -140, 12, 10, 3],
  ];
  for (const [x, z, w, d, h] of insulaSpots) {
    const y = ROME.terrainHeight(x, z);
    const b = new THREE.Mesh(new THREE.BoxGeometry(w, h * 3, d), brick);
    b.position.set(x, y + h * 1.5, z);
    b.rotation.y = Math.random() * 0.6 - 0.3;
    b.castShadow = b.receiveShadow = true;
    scene.add(b);
    const r = new THREE.Mesh(new THREE.BoxGeometry(w + 1, 0.9, d + 1), roof);
    r.position.set(x, y + h * 3 + 0.45, z);
    r.rotation.y = b.rotation.y;
    scene.add(r);
  }
}

