/* ============================================================
 * obelisks.js — Monolithic granite obelisks
 *  - Vatican obelisk (Campus Martius)
 *  - Circus Maximus spina obelisk (in circuses.js)
 *  - Obelisk in front of the Pantheon (Campo Marzio)
 * ============================================================ */
function buildObelisk(scene, x, z, name, h) {
  h = h || 22;
  const y = ROME.terrainHeight(x, z);
  const g = new THREE.Group();
  const base = new THREE.Mesh(new THREE.BoxGeometry(4, 1.2, 4), ROME.MAT.stone);
  base.position.y = 0.6; base.castShadow = true; g.add(base);
  const shaft = new THREE.Mesh(new THREE.ConeGeometry(1.5, h, 4), ROME.MAT.obsidian);
  shaft.position.y = 1.2 + h / 2;
  shaft.rotation.y = Math.PI / 4;
  shaft.castShadow = true;
  g.add(shaft);
  const pyr = new THREE.Mesh(new THREE.ConeGeometry(0.7, 1.8, 4), ROME.MAT.gold);
  pyr.position.y = 1.2 + h + 0.9;
  pyr.rotation.y = Math.PI / 4;
  g.add(pyr);
  g.position.set(x, y, z);
  scene.add(g);
  if (name) ROME.makeLabel(scene, name, x, z, y);
  return g;
}

function initObelisks(scene) {
  buildObelisk(scene, -330, 150, 'Vatican Obelisk (Campus Martius)', 26);
  buildObelisk(scene, 205, -95, 'Obelisk of the Pantheon', 18);
  buildObelisk(scene, -60, 20, 'Obelisk of the Circus (spina)', 24);
}

/* ============================================================
 * columns.js — Monumental columns
 *  - Column of Trajan (Forum, 100 CE) — spiral battle reliefs
 *  - Column of Marcus Aurelius (Capitoline)
 *  - Forum column clusters
 * ============================================================ */
function buildMonumentalColumn(scene, x, z, name, statueColor) {
  const y = ROME.terrainHeight(x, z);
  const g = new THREE.Group();
  const trav = ROME.MAT.travertine, marble = ROME.MAT.marble;
  // base
  const base = new THREE.Mesh(new THREE.BoxGeometry(6, 1.6, 6), ROME.MAT.stone);
  base.position.y = 0.8; base.castShadow = true; g.add(base);
  // fluted shaft with relief band (spiral battle reliefs)
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(1.7, 2.1, 27, 18), trav);
  shaft.position.y = 1.6 + 13.5;
  shaft.castShadow = true;
  g.add(shaft);
  const band = new THREE.Mesh(new THREE.CylinderGeometry(2.16, 2.2, 20, 18), marble);
  band.position.y = 1.6 + 12;
  g.add(band);
  // capital + platform
  const cap = new THREE.Mesh(new THREE.BoxGeometry(4.4, 1.4, 4.4), marble);
  cap.position.y = 30.3; g.add(cap);
  // gilded statue on top
  const statue = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 1.2, 4.5, 8),
    new THREE.MeshStandardMaterial({ color: statueColor || 0xd4af37, metalness: 0.6, roughness: 0.4 }));
  statue.position.y = 34;
  g.add(statue);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.75, 10, 10), statue.material);
  head.position.y = 36.6;
  g.add(head);

  g.position.set(x, y, z);
  scene.add(g);
  ROME.makeLabel(scene, name, x, z, y);
}

function initColumns(scene) {
  buildMonumentalColumn(scene, 60, -40, 'Column of Trajan');
  buildMonumentalColumn(scene, -140, -90, 'Column of Marcus Aurelius');
  buildMonumentalColumn(scene, 30, 45, 'Column of the Forum', 0xcfc8b8);
}

/* ============================================================
 * triumphArches.js — Arch of Titus, Arch of Constantine,
 * Arch of Septimius Severus, Arch of Janus,
 * Arch of Claudius (Porta Maggiore aqueduct arch)
 * ============================================================ */
function buildTriumphalArch(scene, x, z, name, w, h, rotY) {
  w = w || 12; h = h || 18; rotY = rotY || 0;
  const y = ROME.terrainHeight(x, z);
  const g = new THREE.Group();
  const trav = ROME.MAT.travertine, marble = ROME.MAT.marble;

  const pierW = 2.6, gap = w - pierW * 2, archR = gap / 2;
  // piers
  for (const s of [-1, 1]) {
    const pier = new THREE.Mesh(new THREE.BoxGeometry(pierW, h, 6), trav);
    pier.position.set(s * (archR + pierW / 2), h / 2, 0);
    pier.castShadow = true; g.add(pier);
    // Corinthian pilasters (engaged)
    for (const pz of [-2, 0, 2]) {
      const pil = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.45, h * 0.92, 8), marble);
      pil.position.set(s * (archR + pierW / 2), h * 0.46, pz + 2.9);
      g.add(pil);
    }
  }
  // arch
  const arch = new THREE.Mesh(new THREE.TorusGeometry(archR, 1.3, 8, 18, Math.PI), trav);
  arch.position.y = h * 0.6;
  g.add(arch);
  // attic / entablature
  const attic = new THREE.Mesh(new THREE.BoxGeometry(w + 1, h * 0.28, 6.4), trav);
  attic.position.y = h * 0.85;
  attic.castShadow = true;
  g.add(attic);
  // coffered entablature detail
  const ent = new THREE.Mesh(new THREE.BoxGeometry(w + 0.4, 1.2, 5.4), marble);
  ent.position.y = h * 0.6 + 1.2;
  g.add(ent);

  g.position.set(x, y, z);
  g.rotation.y = rotY;
  scene.add(g);
  ROME.makeLabel(scene, name, x, z, y);
}

function initTriumphArches(scene) {
  buildTriumphalArch(scene, 25, -25, 'Arch of Titus', 10, 15, 0.5);
  buildTriumphalArch(scene, 15, 60, 'Arch of Septimius Severus', 14, 20, 0.05);
  buildTriumphalArch(scene, 95, 82, 'Arch of Constantine', 13, 19, 0.7);
  buildTriumphalArch(scene, 65, 25, 'Arch of Janus', 8, 12, -0.4);
  // Arch of Claudius — Claudian aqueduct through Porta Maggiore
  buildTriumphalArch(scene, 560, -190, 'Arch of Claudius (Porta Maggiore)', 12, 16, 0.3);
}

