arguments.content:
/* ============================================================
 * aqueducts.js — Masonry aqueduct channels
 * Arched conduits carrying fresh water across the valleys to
 * the fountains, thermae and private villas.
 *  - Aqua Claudia: crosses the city valley on arches
 *  - Aqua Appia: along the south road
 *  - Aqueduct arches integrated into Porta Maggiore
 * ============================================================ */
function buildAquaeductLine(scene, from, to, name) {
  const fx = from.x, fz = from.z, tx = to.x, tz = to.z;
  const len = Math.hypot(tx - fx, tz - fz);
  const ang = Math.atan2(tz - fz, tx - fx);
  const trav = ROME.MAT.travertine;
  const g = new THREE.Group();
  g.position.set(fx, 0, fz);
  g.rotation.y = Math.PI / 2 - ang;

  // series of arches (piers + arch ring)
  const archSpan = 8, pierW = 1.4, H = 16;
  const n = Math.floor(len / archSpan);
  const pierGeo = new THREE.BoxGeometry(pierW, 1, 1);
  const piers = new THREE.InstancedMesh(pierGeo, trav, n + 1);
  const dummy = new THREE.Object3D();
  for (let i = 0; i <= n; i++) {
    const d = i * archSpan;
    const gy = ROME.terrainHeight(fx + Math.cos(ang) * d, fz + Math.sin(ang) * d);
    dummy.position.set(d, gy, 0);
    dummy.scale.set(pierW, H, 6);
    dummy.updateMatrix();
    piers.setMatrixAt(i, dummy.matrix);
  }
  piers.count = n + 1;
  piers.castShadow = true;
  g.add(piers);
  // arch rings
  const archGeo = new THREE.TorusGeometry(archSpan / 2 - pierW / 2, 0.7, 6, 10, Math.PI);
  for (let i = 0; i < n; i++) {
    const d = (i + 0.5) * archSpan;
    const gy = ROME.terrainHeight(fx + Math.cos(ang) * d, fz + Math.sin(ang) * d);
    const a = new THREE.Mesh(archGeo, trav);
    a.position.set(d, gy, 0);
    g.add(a);
  }
  // water channel on top
  const chan = new THREE.Mesh(new THREE.BoxGeometry(len, 2.2, 4.5), ROME.MAT.marble);
  const midX = (fx + tx) / 2, midZ = (fz + tz) / 2;
  chan.position.y = H + 1.1;
  g.add(chan);
  const water = new THREE.Mesh(new THREE.BoxGeometry(len, 0.5, 3.4), ROME.MAT.water);
  water.position.y = H + 2.0;
  g.add(water);
  // NOTE: channel follows straight line; terrain varies — acceptable for scale
  scene.add(g);
  if (name) ROME.makeLabel(scene, name, midX, midZ, H + 6);
}

function initAqueducts(scene) {
  // Aqua Claudia over the valley east→west
  buildAquaeductLine(scene, { x: 480, z: -520 }, { x: -250, z: -140 }, 'Aqua Claudia');
  // Aqua Appia along the south
  buildAquaeductLine(scene, { x: 500, z: 380 }, { x: 150, z: 520 }, 'Aqua Appia');
}

/* ============================================================
 * fountains.js — Public fountains (nymphaea & lararia)
 * fed by the aqueducts: Mocho fountain, Forum fountain,
 * Campus Martius fountain, baths basin.
 * ============================================================ */
function buildFountain(scene, x, z, name, size) {
  size = size || 1;
  const y = ROME.terrainHeight(x, z);
  const g = new THREE.Group();
  const marble = ROME.MAT.marble, stone = ROME.MAT.stone, water = ROME.MAT.water;

  // outer basin
  const rim = new THREE.Mesh(new THREE.CylinderGeometry(8 * size, 8.4 * size, 1.6 * size, 18, 1, true), marble);
  rim.position.y = 0.8 * size; rim.castShadow = true; g.add(rim);
  const base = new THREE.Mesh(new THREE.CylinderGeometry(8.4 * size, 8.8 * size, 0.5 * size, 18), stone);
  base.position.y = 0.25 * size; g.add(base);
  const innerWater = new THREE.Mesh(new THREE.CylinderGeometry(7.9 * size, 7.9 * size, 0.5 * size, 18), water);
  innerWater.position.y = 1.3 * size; g.add(innerWater);
  // central pedestal + jet
  const ped = new THREE.Mesh(new THREE.CylinderGeometry(1.6 * size, 2.2 * size, 3.4 * size, 12), marble);
  ped.position.y = 1.7 * size; ped.castShadow = true; g.add(ped);
  const jet = new THREE.Mesh(new THREE.CylinderGeometry(0.5 * size, 0.8 * size, 2.2 * size, 10), water);
  jet.position.y = 4.2 * size; g.add(jet);
  // four small jets
  for (let i = 0; i < 4; i++) {
    const a = i / 4 * Math.PI * 2 + Math.PI / 4;
    const j = new THREE.Mesh(new THREE.CylinderGeometry(0.25 * size, 0.35 * size, 1.4 * size, 8), water);
    j.position.set(Math.cos(a) * 5 * size, 0.9 * size, Math.sin(a) * 5 * size);
    g.add(j);
  }

  g.position.set(x, y, z);
  scene.add(g);
  if (name) ROME.makeLabel(scene, name, x, z, y);
}

function initFountains(scene) {
  buildFountain(scene, -300, 200, 'Mocho Fountain (Campus Martius)', 1.6);
  buildFountain(scene, -15, 20, 'Fountain of the Forum (Fons)', 1.2);
  buildFountain(scene, 60, -110, 'Fountain near the Forum (Aemilia)', 1.0);
  buildFountain(scene, -250, -10, 'Lararium of the Boarium', 0.9);
}

/* ============================================================
 * villas.js — Country estates outside the walls
 *  - Villa Urbana (leisure retreat) on the Via Appia
 *  - Villa Rustica (working farm) along the Via Flaminia
 *  - Villa Marittima at the Tiber bank
 * Layout: atrium with impluvium courtyard, peristyle garden
 * colonnade, residential wing + agricultural wing.
 * ============================================================ */
function buildVilla(scene, x, z, name, kind) {
  const y = ROME.terrainHeight(x, z);
  const trav = ROME.MAT.travertine, brick = ROME.MAT.brick;
  const marble = ROME.MAT.marble, roof = ROME.MAT.roof, water = ROME.MAT.water;
  const g = new THREE.Group();

  const W = 44, D = 30, wallH = 6;

  // residential wing (pars urbana): U-shaped around courtyard
  const blocks = [
    [-W / 4, -D / 4, W / 2, D / 4],   // north
    [-W / 4, D / 4, W / 2, D / 4],    // south
    [-W / 4, 0, W / 4, D],            // west (atrium wing)
    [W / 4, -D / 4, W / 4, D / 2],    // east (triclinium)
  ];
  for (const [bx, bz, bw, bd] of blocks) {
    const b = new THREE.Mesh(new THREE.BoxGeometry(bw, wallH, bd), trav);
    b.position.set(bx, wallH / 2, bz);
    b.castShadow = b.receiveShadow = true;
    g.add(b);
    const r = new THREE.Mesh(new THREE.BoxGeometry(bw + 0.8, 0.8, bd + 0.8), roof);
    r.position.set(bx, wallH + 0.4, bz);
    g.add(r);
  }
  // atrium impluvium (water basin where rain fell through oculus)
  const impl = new THREE.Mesh(new THREE.BoxGeometry(8, 0.6, 8), water);
  impl.position.set(-W / 4, 0.5, 0);
  g.add(impl);
  const implRim = new THREE.Mesh(new THREE.BoxGeometry(10, 1.0, 10), marble);
  implRim.position.set(-W / 4, 0.3, 0);
  g.add(implRim);
  // peristyle: colonnaded garden on the east side
  const colGeo = new THREE.CylinderGeometry(0.5, 0.55, 4.6, 10);
  for (let i = 0; i <= 5; i++) {
    for (const s of [-1, 1]) {
      const c = new THREE.Mesh(colGeo, marble);
      c.position.set(W / 4 - 3, 2.3, s * (D / 2 - 3) + (s > 0 ? -D / 5 : D / 5));
      g.add(c);
      const c2 = new THREE.Mesh(colGeo, marble);
      c2.position.set(W / 4 - 3 + (i - 2.5) * 3, 2.3, 0);
      g.add(c2);
    }
  }
  // garden pool
  const pool = new THREE.Mesh(new THREE.BoxGeometry(10, 0.5, 4), water);
  pool.position.set(W / 4, 0.4, 0);
  g.add(pool);

  if (kind === 'rustica') {
    // agricultural wing: barns, granaries, press yard
    for (let i = 0; i < 3; i++) {
      const barn = new THREE.Mesh(new THREE.BoxGeometry(10, 4, 7), brick);
      barn.position.set(-W / 2 - 10, 2, -12 + i * 12);
      barn.castShadow = true;
      g.add(barn);
      const br = new THREE.Mesh(new THREE.ConeGeometry(5.2, 2, 4), ROME.MAT.wood);
      br.position.set(-W / 2 - 10, 5, -12 + i * 12);
      br.rotation.y = Math.PI / 4;
      g.add(br);
    }
    // wine amphora storage yard
    const yard = new THREE.Mesh(new THREE.BoxGeometry(12, 0.4, 16), ROME.MAT.roadStone);
    yard.position.set(-W / 2 - 10, 0.2, 14);
    g.add(yard);
  }
  if (kind === 'marittima') {
    // pier into the river
    const pier = new THREE.Mesh(new THREE.BoxGeometry(6, 1, 30), ROME.MAT.stone);
    pier.position.set(0, 0.5, D / 2 + 12);
    g.add(pier);
  }

  g.position.set(x, y, z);
  g.rotation.y = Math.random() * 0.8 - 0.4;
  scene.add(g);
  ROME.makeLabel(scene, name, x, z, y);
}

function initVillas(scene) {
  buildVilla(scene, 640, 780, 'Villa Urbana (via Appia)', 'urbana');
  buildVilla(scene, 130, -1020, 'Villa Rustica (via Flaminia)', 'rustica');
  buildVilla(scene, -600, -250, 'Villa Marittima (Tiber bank)', 'marittima');
}

