  ['forum ground', ROME.terrainHeight(0, 0), v => v > -1],
  ['palatine peak', ROME.terrainHeight(0, -110), v => v > 25],
  ['river bed', ROME.terrainHeight(ROME.riverX(150), 150), v => v < -3],
  ['river bank dry', ROME.terrainHeight(ROME.riverX(150) + 100, 150), v => v > -1],
  ['wall pt vs river z=150', null, v => true],
];
for (const [n, v, ok] of checks) console.log(n.padEnd(20), v == null ? '' : v.toFixed(1), ok(v == null ? 0 : v) ? 'ok' : 'CHECK!');

let count = 0; scene.traverse(() => count++);
console.log('scene objects:', count);
console.log('SMOKE TEST PASSED');

